# coding: utf-8
"""Один файл для восстановления проекта и запуска сборки GitHub Actions."""
from pathlib import Path
import base64, io, zipfile, subprocess, sys
PROJECT_B64 = """"""
WORKFLOW = "name: Build Android APK\non:\n  push:\n    branches: [main, master]\n  workflow_dispatch:\npermissions:\n  contents: read\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: actions/setup-java@v4\n        with:\n          distribution: temurin\n          java-version: '17'\n      - uses: android-actions/setup-android@v3\n      - name: Install Android SDK\n        run: sdkmanager 'platforms;android-35' 'build-tools;35.0.0'\n      - name: Install Gradle\n        uses: gradle/actions/setup-gradle@v4\n        with:\n          gradle-version: '8.7'\n      - name: Build APK\n        run: gradle --no-daemon assembleDebug\n      - name: Upload APK\n        uses: actions/upload-artifact@v4\n        with:\n          name: GeometryDashAgent-debug-apk\n          path: app/build/outputs/apk/debug/*.apk\n"

def run():
    root = Path(__file__).resolve().parent
    archive = zipfile.ZipFile(io.BytesIO(base64.b64decode(PROJECT_B64)))
    for item in archive.infolist():
        target = (root / item.filename).resolve()
        if not target.is_relative_to(root):
            raise RuntimeError("Недопустимый путь в архиве")
        if item.is_dir():
            target.mkdir(parents=True, exist_ok=True)
        else:
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.read(item))
    wf = root / '.github' / 'workflows' / 'build-apk.yml'
    wf.parent.mkdir(parents=True, exist_ok=True)
    wf.write_text(WORKFLOW, encoding='utf-8')
    print('Созданы исходники Android и GitHub Actions.')
    cmds = [['git','add','.'],['git','-c','user.name=Android Bot Setup','-c','user.email=setup@users.noreply.github.com','commit','-m','Set up Android APK build'],['git','push']]
    for cmd in cmds:
        print('>', ' '.join(cmd), flush=True)
        result = subprocess.run(cmd, cwd=root, check=False)
        if result.returncode != 0:
            print('Не удалось выполнить команду. Проверь доступ к репозиторию и повтори вручную:', ' '.join(cmd))
            return result.returncode
    print('Готово. Открой GitHub → Actions → Build Android APK → Artifacts.')
    return 0
if __name__ == '__main__':
    sys.exit(run())
